ct"] = tAprilOneToOneAdvance_Data["Effect"]		-- 3307883 明亮星陨石*10礼包	tAprilOneToOneAdvance_Reward[3307883] = {}	tAprilOneToOneAdvance_Reward[3307883]["RewardItem"] = {}	tAprilOneToOneAdvance_Reward[3307883]["RewardItem"][1] = {}	tAprilOneToOneAdvance_Reward[3307883]["RewardItem"][1]["Id"] = 3009001	tAprilOneToOneAdvance_Reward[3307883]["RewardItem"][1]["Attr"] = "0 10 0 2880 1"	tAprilOneToOneAdvance_Reward[3307883]["DeleteItem"] = {}	tAprilOneToOneAdvance_Reward[3307883]["DeleteItem"][1] = {}	tAprilOneToOneAdvance_Reward[3307883]["DeleteItem"][1]["Id"] = 3307883	tAprilOneToOneAdvance_Reward[3307883]["LogId"] = tAprilOneToOneAdvance_Data["LogId"]	tAprilOneToOneAdvance_Reward[3307883]["RewardEffect"] = {}	tAprilOneToOneAdvance_Reward[3307883]["RewardEffect"]["Effect"] = tAprilOneToOneAdvance_Data["Effect"]		-- 3307884 良品天怒宝石（赠）*6礼包	tAprilOneToOneAdvance_Reward[3307884] = {}	tAprilOneToOneAdvance_Reward[3307884]["RewardItem"] = {}	tAprilOneToOneAdvance_Reward[3307884]["RewardItem"][1] = {}	tAprilOneToOneAdvance_Reward[3307884]["RewardItem"][1]["Id"] = 700102	tAprilOneToOneAdvance_Reward[3307884]["RewardItem"][1]["Attr"] = "0 6 3"	tAprilOneToOneAdvance_Reward[3307884]["DeleteItem"] = {}	tAprilOneToOneAdvance_Reward[3307884]["DeleteItem"][1] = {}	tAprilOneToOneAdvance_Reward[3307884]["DeleteItem"][1]["Id"] = 3307884	tAprilOneToOneAdvance_Reward[3307884]["LogId"] = tAprilOneToOneAdvance_Data["LogId"]	tAprilOneToOneAdvance_Reward[3307884]["RewardEffect"] = {}	tAprilOneToOneAdvance_Reward[3307884]["RewardEffect"]["Effect"] = tAprilOneToOneAdvance_Data["Effect"]	local tAprilOneToOneAdvance_Num = {}--二进制的值	for i = 1,5 do		tAprilOneToOneAdvance_Num[i] = 2^(i-1)	end--------------------------------------逻辑部分--------------------------------------------- 购买选项function AprilOneToOneAdvance_OpenOption(nItemId,nIndex)	-- 判断物品	if not Item_ChkItem(nItemId) then		Sys_MsgBox(tAprilOneToOneAdvance_Text[nItemId]["NoItem"])		return	end		-- 判断时间	-- 后	if CommonFunc_GetAfterActivityTime(tActivityTime["AprilOneToOneAdvance"]["ActivityTime"]) then		Item_DelItem(nItemId)		User_TalkChannel2005(tAprilOneToOneAdvance_Text["Overdue"])		Sys_SaveActionFestivalLog(tAprilOneToOneAdvance_Data["Log"]["OverdueDelete"])		return	end		-- 判断打开情况 5次则直接删除	local nOpenTimes = AprilOneToOneAdvance_OpenTimes(nItemId)	if nOpenTimes == tAprilOneToOneAdvance_Data["OpenTimesLimit"] then		Item_DelItem(nItemId)		return	end	-- 判断打开情况 选项物品已购买过	if AprilOneToOneAdvance_IfPurchased(nItemId,nIndex) then		return	end		-- 判断天石	local nNeedEMoney = tAprilOneToOneAdvance_Data["EmoneyMono"][nItemId]	if Get_UserEMoney() < nNeedEMoney then		Sys_MsgBox(tAprilOneToOneAdvance_Text[nItemId]["NoEmoney"])		return	end		-- 判断背包	local nSpace = RewardTemplate_GetRewardSpace(tAprilOneToOneAdvance_Reward[nItemId][nIndex])	-- 最后一次购买珍宝时所需背包空间-1	if nOpenTimes == tAprilOneToOneAdvance_Data["OpenTimesLimit"] - 1 then		if nSpace > 0 then			nSpace = nSpace - 1		end	end	if nSpace > 0 then		if not User_CheckLeftSpace(nSpace) then			local sMsg = string.format(tAprilOneToOneAdvance_Text[nItemId]["NoSpace"],nSpace)			Sys_MsgBox(sMsg)			return		end	end		---------------------------------------------------		-- 扣除天石	if not User_AddEMoney(-nNeedEMoney) then		return	end		-- 最后一次购买珍宝时删除礼包	if nOpenTimes == tAprilOneToOneAdvance_Data["OpenTimesLimit"] - 1 then		if not Item_DelItem(nItemId) then			return		end	end		-- 打掩码	local nEventType = tAprilOneToOneAdvance_Data["Stc"][nItemId]["EventType"]	local nDataType = tAprilOneToOneAdvance_Data["Stc"][nItemId]["DataType"]	Task_AddStatistic(nEventType,nDataType,tAprilOneToOneAdvance_Num[nIndex],1)		-- 给奖	RewardTemplate_UseItemAndMsg(tAprilOneToOneAdvance_Reward[nItemId][nIndex])end-- 判断礼包打开情况function AprilOneToOneAdvance_OpenTimes(nItemId)	local nEventType = tAprilOneToOneAdvance_Data["Stc"][nItemId]["EventType"]	local nDataType = tAprilOneToOneAdvance_Data["Stc"][nItemId]["DataType"]	local nValue = Get_UserStatisticValue(nEventType,nDataType)	local nTimes = 0	for i = 1,5 do		if Sys_ParseNumbersContain(tAprilOneToOneAdvance_Num[i],nValue) then			nTimes = nTimes + 1		end	end	return nTimesend-- 判断礼包购买情况function AprilOneToOneAdvance_IfPurchased(nItemId,nIndex)	local nEventType = tAprilOneToOneAdvance_Data["Stc"][nItemId]["EventType"]	local nDataType = tAprilOneToOneAdvance_Data["Stc"][nItemId]["DataType"]	local nValue = Get_UserStatisticValue(nEventType,nDataType)	if Sys_ParseNumbersContain(tAprilOneToOneAdvance_Num[nIndex],nValue) then		return true	end		return falseend-- 3307882 极品宝石（赠）可选包function AprilOneToOneAdvance_OpenPack(nItemId,nIndex)	-- 判断物品	if not Item_ChkItem(nItemId) then		Sys_MsgBox(tAprilOneToOneAdvance_Text[nItemId]["NoItem"])		return	end		-- 判断时间	-- 后	if CommonFunc_GetAfterActivityTime(tActivityTime["AprilOneToOneAdvance"]["ActivityTime"]) then		Item_DelItem(nItemId)		User_TalkChannel2005(tAprilOneToOneAdvance_Text["Overdue"])		Sys_SaveActionFestivalLog(tAprilOneToOneAdvance_Data["Log"]["OverdueDelete"])		return	end		RewardTemplate_UseItemAndMsg(tAprilOneToOneAdvance_Reward[nItemId][nIndex])end--------------------------------------物品配置--------------------------------------------- 3307880 9天石神秘商店礼盒-- 3307881 49天石神秘商店礼盒tItemFace[3307880] = 424tItemFace[3307881] = 426for i = 3307880,3307881 dotItem[i] = tItem[i] or {}tItem[i]["DialogueText"] = tAprilOneToOneAdvance_Text[i]tItem[i]["Function"] = function(nItemId,sItemName)	-- 判断物品	if not Item_ChkItem(nItemId) then		Sys_MsgBox(tAprilOneToOneAdvance_Text[nItemId]["NoItem"])		return	end		-- 判断时间	-- 后	if CommonFunc_GetAfterActivityTime(tActivityTime["AprilOneToOneAdvance"]["ActivityTime"]) then		Item_DelItem(nItemId)		User_TalkChannel2005(tAprilOneToOneAdvance_Text["Overdue"])		Sys_SaveActionFestivalLog(tAprilOneToOneAdvance_Data["Log"]["OverdueDelete"])		return	end		-- 判断打开情况 5次则直接删除	local nOpenTimes = AprilOneToOneAdvance_OpenTimes(nItemId)	if nOpenTimes == tAprilOneToOneAdvance_Data["OpenTimesLimit"] then		Item_DelItem(nItemId)		return	end		LinkItemGossipFunc_New(nItemId,"1-1")endtItem[i]["Text1-1"] = {111,112,113,114,1111,1112,1113,1114,1115,115,116}tItem[i]["tOption1-1"] = {1,2,3,4,5,6}tItem[i]["ChkFunc1-1"] = function()	local nItemId = i	for j = 1,5 do		if AprilOneToOneAdvance_IfPurchased(nItemId,j) then			tItem[nItemId]["Text111" .. j] = tAprilOneToOneAdvance_Text[nItemId]["Text111" .. j] .. tAprilOneToOneAdvance_Text["Purchased"]		else			tItem[nItemId]["Text111" .. j] = tAprilOneToOneAdvance_Text[nItemId]["Text111" .. j]		end	end		return trueendtItem[i]["OptionChkFunc1"] = function ()	local nItemId = i	if AprilOneToOneAdvance_IfPurchased(nItemId,1) then		return false	end		return trueendtItem[i]["OptionChkFunc2"] = function ()	local nItemId = i	if AprilOneToOneAdvance_IfPurchased(nItemId,2) then		return false	end		return trueendtItem[i]["OptionChkFunc3"] = function ()	local nItemId = i	if AprilOneToOneAdvance_IfPurchased(nItemId,3) then		return false	end		return trueendtItem[i]["OptionChkFunc4"] = function ()	local nItemId = i	if AprilOneToOneAdvance_IfPurchased(nItemId,4) then		return false	end		return trueendtItem[i]["OptionChkFunc5"] = function ()	local nItemId = i	if AprilOneToOneAdvance_IfPurchased(nItemId,5) then		return false	end		return trueendtItem[i]["OptionPoint1"] = "2-1"tItem[i]["OptionPoint2"] = "2-2"tItem[i]["OptionPoint3"] = "2-3"tItem[i]["OptionPoint4"] = "2-4"tItem[i]["OptionPoint5"] = "2-5"tItem[i]["Text2-1"] = {211}tItem[i]["tOption2-1"] = {211,212}tItem[i]["OptionFunc211"] = string.format("AprilOneToOneAdvance_OpenOption</N>%d</N>1",i)tItem[i]["OptionPoint212"] = "1-1"tItem[i]["Text2-2"] = {221}tItem[i]["tOption2-2"] = {221,212}tItem[i]["OptionFunc221"] = string.format("AprilOneToOneAdvance_OpenOption</N>%d</N>2",i)tItem[i]["Text2-3"] = {231}tItem[i]["tOption2-3"] = {231,212}tItem[i]["OptionFunc231"] = string.format("AprilOneToOneAdvance_OpenOption</N>%d</N>3",i)tItem[i]["Text2-4"] = {241}tItem[i]["tOption2-4"] = {241,212}tItem[i]["OptionFunc241"] = string.format("AprilOneToOneAdvance_OpenOption</N>%d</N>4",i)tItem[i]["Text2-5"] = {251}tItem[i]["tOption2-5"] = {251,212}tItem[i]["OptionFunc251"] = string.format("AprilOneToOneAdvance_OpenOption</N>%d</N>5",i)end-- 3307882 极品宝石（赠）可选包tItemFace[3307882] = 953tItem[3307882] = tItem[3307882] or {}tItem[3307882]["DialogueText"] = tAprilOneToOneAdvance_Text[3307882]tItem[3307882]["Function"] = function(nItemId,sItemName)	-- 判断物品	if not Item_ChkItem(nItemId) then		Sys_MsgBox(tAprilOneToOneAdvance_Text[nItemId]["NoItem"])		return	end		-- 判断时间	-- 后	if CommonFunc_GetAfterActivityTime(tActivityTime["AprilOneToOneAdvance"]["ActivityTime"]) then		Item_DelItem(nItemId)		User_TalkChannel2005(tAprilOneToOneAdvance_Text["Overdue"])		Sys_SaveActionFestivalLog(tAprilOneToOneAdvance_Data["Log"]["OverdueDelete"])		return	end		LinkItemGossipFunc_New(nItemId,"1-1")endtItem[3307882]["Text1-1"] = {111}tItem[3307882]["tOption1-1"] = {1,2}tItem[3307882]["OptionFunc1"] = "AprilOneToOneAdvance_OpenPack</N>3307882</N>1"tItem[3307882]["OptionFunc2"] = "AprilOneToOneAdvance_OpenPack</N>3307882</N>2"-- 3307883 明亮星陨石*10礼包-- 3307884 良品天怒宝石（赠）*6礼包tItem[3307883] = tItem[3307883] or {}tItem[3307884] = tItem[3307883] or {}tItem[3307883]["Function"] = function(nItemId,sItemName)	-- 判断时间	-- 后	if CommonFunc_GetAfterActivityTime(tActivityTime["AprilOneToOneAdvance"]["ActivityTime"]) then		Item_DelItem(nItemId)		User_TalkChannel2005(tAprilOneToOneAdvance_Text["Overdue"])		Sys_SaveActionFestivalLog(tAprilOneToOneAdvance_Data["Log"]["OverdueDelete"])		return	end		RewardTemplate_UseItemAndMsg(tAprilOneToOneAdvance_Reward[nItemId])end